pdf.body:


	


		Vendor:
		


		${record.billaddress}
		
	
	


		Bill To:
		


		${record.custbody_tc_subsidiary_address}
          
		
	
	


		${record.shipaddress@label}:
		


		${record.shipaddress}
		
	
	



	Order Date
	Requested Delivery Date
	Payment Terms
	Currency
	Incoterms
	Buyer Details
	


	${record.trandate}
	${record.duedate}
	${record.terms}
	${record.currencysymbol}
	${record.incoterm}
	${record.custbody_tc_created_by.firstname} ${record.custbody_tc_created_by.lastname}
${record.custbody_tc_created_by.email}
	

<#if record.item?has_content>
<#list record.item as item><#if item_index==0>



	${item.item@label}
    Requested Date
	${item.quantity@label}
	${item.rate@label}
	${item.amount@label}
	

</#if>

	${item.item}
${item.description}
    ${item.custcol_tc_requested_date}
	${item.quantity}
	${item.rate}
	${item.amount}
	
	</#list>
</#if><#if record.expense?has_content>

<#list record.expense as expense ><#if expense_index==0>



	Item
	Quantity
	Rate
	Amount
	

</#if>

	${expense.memo}
	${expense.custcol_tc_item_qty}
	${expense.custcol_tc_item_price}
	${expense.amount}
	
	</#list>
</#if>




	 
	${record.subtotal@label}
	${record.subtotal}
	
	<#if record.discounttotal?has_content && record.discounttotal != 0>


	 
	Discounts
	${record.discounttotal}
	
	</#if>
  	<#if record.item?has_content>
      <#if record.subsidiary == "TCC" || record.subsidiary == "TCA">


        
        <#if record.taxtotal?has_content>GST/HST(${record.item[0].taxrate1})<#else> </#if>
        <#if record.taxtotal?has_content>${record.taxtotal}<#else> </#if>
        


          
          ${record.tax2total@label} <#if record.item[0].taxrate2!=0>(${record.item[0].taxrate2})<#else> </#if>
          <#if record.taxtotal?has_content>${record.tax2total}<#else> </#if>
        
      <#elseif record.subsidiary == "TCU" || record.subsidiary == "TRE">


        
        <#if record.taxtotal?has_content>US Sales Tax<#else> </#if>
        <#if record.taxtotal?has_content>${record.taxtotal}<#else> </#if>
        
      </#if>
    </#if>
    <#if record.expense?has_content>
      <#if record.subsidiary == "TCC" || record.subsidiary == "TCA">


        
        <#if record.taxtotal?has_content>GST/HST(${record.expense[0].taxrate1})<#else> </#if>
        <#if record.taxtotal?has_content>${record.taxtotal}<#else> </#if>
        


          
          ${record.tax2total@label} <#if record.expense[0].taxrate2!=0>(${record.expense[0].taxrate2})<#else> </#if>
          <#if record.taxtotal?has_content>${record.tax2total}<#else> </#if>
        
      <#elseif record.subsidiary == "TCU" || record.subsidiary == "TRE">


        
        <#if record.taxtotal?has_content>US Sales Tax<#else> </#if>
        <#if record.taxtotal?has_content>${record.taxtotal}<#else> </#if>
        
      </#if>
    </#if>
	<#if record.shippingcost?has_content>


	 
	${record.shippingcost@label}
	${record.shippingcost}
	
	</#if>


	 
	${record.total@label}
	${record.total}
